from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda c: sum(row.count(c) for row in grid))
    seen = set(); comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen: continue
            q = [(r, c)]; seen.add((r, c)); pts = []
            while q:
                y, x = q.pop(); pts.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    z = (y+dy, x+dx)
                    if 0 <= z[0] < h and 0 <= z[1] < w and z not in seen and grid[z[0]][z[1]] == color:
                        seen.add(z); q.append(z)
            comps.append((color, pts))
    def variants(pts):
        result = []
        for reflect in (1, -1):
            for rot in range(4):
                a = []
                for y, x in pts:
                    x *= reflect
                    for _ in range(rot): y, x = x, -y
                    a.append((y, x))
                my, mx = min(y for y,x in a), min(x for y,x in a)
                result.append([(y-my, x-mx) for y,x in a])
        return result
    def contained(small, large):
        for form in variants(small):
            fh = max(y for y,x in form)+1; fw = max(x for y,x in form)+1
            for oy in range(h-fh+1):
                for ox in range(w-fw+1):
                    if all((oy+y, ox+x) in large for y,x in form): return True
        return False
    # Recolor a small object to the color of the larger object containing its shape.
    for i, (color, pts) in enumerate(comps):
        for j, (other, big) in enumerate(comps):
            if i != j and len(pts) < len(big) and contained(pts, set(big)):
                out = [row[:] for row in grid]
                for y,x in pts: out[y][x] = other
                return out
    return [row[:] for row in grid]
